// src/App.js
import React, { useEffect } from "react";
import { BrowserRouter as Router, Route, Routes, Navigate, useNavigate } from "react-router-dom";
import Login from "./pages/Login";
import Register from "./pages/Register";
import AdminDashboard from "./pages/AdminDashboard";
import StudentDashboard from "./pages/StudentDashboard";
import InstituteDashboard from "./pages/InstituteDashboard";
import CompanyDashboard from "./pages/CompanyDashboard";
import { AuthProvider, useAuth } from "./context/AuthContext";

// PrivateRoute component for role-based access
function PrivateRoute({ children, role }) {
  const { currentUser } = useAuth();

  if (!currentUser) return <Navigate to="/login" />;
  if (role && currentUser.role !== role) return <Navigate to="/login" />;

  return children;
}

// DashboardRedirect component automatically sends user to their dashboard
function DashboardRedirect() {
  const { currentUser } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    if (currentUser) {
      switch (currentUser.role) {
        case "admin":
          navigate("/admin-dashboard");
          break;
        case "student":
          navigate("/student-dashboard");
          break;
        case "institution":
          navigate("/institute-dashboard");
          break;
        case "company":
          navigate("/company-dashboard");
          break;
        default:
          navigate("/login");
      }
    } else {
      navigate("/login");
    }
  }, [currentUser, navigate]);

  return null; // nothing to render while redirecting
}

function App() {
  return (
    <AuthProvider>
      <Router>
        <Routes>
          {/* Default route will redirect based on user role */}
          <Route path="/" element={<DashboardRedirect />} />

          {/* Authentication pages */}
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />

          {/* Dashboards */}
          <Route
            path="/admin-dashboard"
            element={
              <PrivateRoute role="admin">
                <AdminDashboard />
              </PrivateRoute>
            }
          />
          <Route
            path="/student-dashboard"
            element={
              <PrivateRoute role="student">
                <StudentDashboard />
              </PrivateRoute>
            }
          />
          <Route
            path="/institute-dashboard"
            element={
              <PrivateRoute role="institution">
                <InstituteDashboard />
              </PrivateRoute>
            }
          />
          <Route
            path="/company-dashboard"
            element={
              <PrivateRoute role="company">
                <CompanyDashboard />
              </PrivateRoute>
            }
          />

          {/* Catch-all redirect */}
          <Route path="*" element={<Navigate to="/" />} />
        </Routes>
      </Router>
    </AuthProvider>
  );
}

export default App;
